import{_ as n,c as s,o as a,a as p}from"./app-olgpHTCG.js";const t="/images/rewrite/pattern-strategy/change-scope.webp",e="/images/rewrite/pattern-strategy/structure.webp",o={},c=p(`<h1 id="策略模式-strategy" tabindex="-1"><a class="header-anchor" href="#策略模式-strategy"><span>策略模式（Strategy）</span></a></h1><h2 id="核心要点" tabindex="-1"><a class="header-anchor" href="#核心要点"><span>核心要点</span></a></h2><ul><li><strong>定义</strong>：把一组做同类事情的算法分别封装成独立的单元，让它们对外长得一样（入参、返回值一致），从而可以随时互相替换。</li><li><strong>一句话理解</strong>：同一个入口，传进来的「类型 / 参数」不同，就命中不同的处理策略。</li><li><strong>三个关键词怎么落地</strong>： <ul><li>「算法」：任何一段业务计算逻辑，比如运费怎么算、积分怎么给、字段怎么校验；</li><li>「封装」：把每种逻辑单独抽成一个函数（或类），各管各的；</li><li>「可替换」：用一张「key → 策略」的映射表来选择策略，而不是在一个函数里堆 if-else。</li></ul></li><li><strong>好处</strong>：干掉成片的 if-else / switch；每个策略可以单独复用、单独测试；新增一种情况只加一条映射，不改老代码。</li><li><strong>背后的两条设计原则</strong>： <ul><li>单一职责：一个函数只处理一种算法，出 Bug 能精确定位，修一个不会连累其他；</li><li>开放封闭：对扩展开放（加新策略）、对修改封闭（分发逻辑和老策略不动），测试只需要覆盖新增的那条。</li></ul></li><li><strong>重构路线</strong>：if-else 大函数 → 先把每段逻辑拆成独立函数（解决「执行」）→ 再用对象映射取代条件判断（解决「分发」）。</li><li><strong>工程上的封装</strong>：策略表和分发函数放进一个模块，只 <code>export</code> 对外的方法，调用方 <code>import</code> 后按 key 调用。</li><li><strong>常见应用</strong>：价格 / 运费 / 折扣计算、表单校验规则、不同环境的上报方式、动画缓动函数、权限或路由的分支处理。</li><li><strong>补充注意点</strong>：查表前要处理未知 key（否则会报 <code>xxx is not a function</code>，普通对象还可能命中原型上的 <code>toString</code> 之类的方法），可以用 <code>Object.hasOwn</code>、<code>Object.create(null)</code> 或 <code>Map</code>。</li></ul><h2 id="先看一个最小例子" tabindex="-1"><a class="header-anchor" href="#先看一个最小例子"><span>先看一个最小例子</span></a></h2><p>商城会员下单后按等级返积分：白银会员 1 倍、黄金会员 1.5 倍、钻石会员 2 倍。按等级去查一个对象就能拿到对应的计算方式：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// points.js</span></span>
<span class="line"><span class="token keyword">const</span> pointRules <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">silver</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">spent</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>spent <span class="token operator">*</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">gold</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">spent</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>spent <span class="token operator">*</span> <span class="token number">1.5</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">diamond</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">spent</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>spent <span class="token operator">*</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">earnPoints</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">tier<span class="token punctuation">,</span> spent</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> pointRules<span class="token punctuation">[</span>tier<span class="token punctuation">]</span><span class="token punctuation">(</span>spent<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token function">earnPoints</span><span class="token punctuation">(</span><span class="token string">&#39;gold&#39;</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 450</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 规则表留在模块内部，只把计算入口暴露出去</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token punctuation">{</span> earnPoints <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>别的文件这样用：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">import</span> points <span class="token keyword">from</span> <span class="token string">&#39;./points.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">points<span class="token punctuation">.</span><span class="token function">earnPoints</span><span class="token punctuation">(</span><span class="token string">&#39;diamond&#39;</span><span class="token punctuation">,</span> <span class="token number">88</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 176</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里已经包含了策略模式的全部要素：</p><table><thead><tr><th>角色</th><th>在例子里对应什么</th></tr></thead><tbody><tr><td>一组策略（算法）</td><td><code>pointRules</code> 里的三个函数，签名都是 <code>(spent) =&gt; number</code></td></tr><tr><td>选择策略的依据</td><td>会员等级 <code>tier</code></td></tr><tr><td>上下文 / 分发者</td><td><code>earnPoints</code>，按等级找到策略并执行</td></tr><tr><td>封装边界</td><td>模块只导出 <code>earnPoints</code>，规则表对外不可见</td></tr></tbody></table><p>好处很直接：没有一条 <code>if</code>，规则也都能单独拿出来复用。下面用一个更接近真实业务的场景，完整走一遍「从 if-else 到策略模式」的重构。</p><h2 id="实战场景-结算页的运费计算" tabindex="-1"><a class="header-anchor" href="#实战场景-结算页的运费计算"><span>实战场景：结算页的运费计算</span></a></h2><p>结算页要根据用户选择的配送方式算运费，规则如下：</p><table><thead><tr><th>配送方式</th><th>标识</th><th>运费规则</th></tr></thead><tbody><tr><td>普通快递</td><td><code>standard</code></td><td>订单满 99 元包邮，不满收 8 元</td></tr><tr><td>次日达</td><td><code>express</code></td><td>固定 15 元，订单满 199 元运费减半</td></tr><tr><td>同城闪送</td><td><code>sameDay</code></td><td>首重 1kg 收 12 元，之后每 kg（向上取整）加 4 元</td></tr><tr><td>门店自提</td><td><code>pickup</code></td><td>免运费</td></tr></tbody></table><p>先给每种方式起一个英文标识（上表第二列），代码里就用这个标识来区分。</p><h3 id="直觉写法-一个函数包办一切" tabindex="-1"><a class="header-anchor" href="#直觉写法-一个函数包办一切"><span>直觉写法：一个函数包办一切</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// 根据配送方式和订单信息返回运费</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">calcShipping</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> order</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> amount<span class="token punctuation">,</span> weight <span class="token punctuation">}</span> <span class="token operator">=</span> order<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 普通快递</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;standard&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">99</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">8</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 次日达</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;express&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">199</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">15</span> <span class="token operator">/</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">15</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 同城闪送</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;sameDay&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> extraKg <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">ceil</span><span class="token punctuation">(</span>weight<span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">12</span> <span class="token operator">+</span> extraKg <span class="token operator">*</span> <span class="token number">4</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 门店自提</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;pickup&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> order <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">amount</span><span class="token operator">:</span> <span class="token number">120</span><span class="token punctuation">,</span> <span class="token literal-property property">weight</span><span class="token operator">:</span> <span class="token number">2.3</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">[</span><span class="token string">&#39;standard&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;express&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;sameDay&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;pickup&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">m</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">calcShipping</span><span class="token punctuation">(</span>m<span class="token punctuation">,</span> order<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// [0, 15, 20, 0]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>功能上完全正确，跑起来也没问题。问题出在「以后」。</p><h2 id="这种写法哪里不好" tabindex="-1"><a class="header-anchor" href="#这种写法哪里不好"><span>这种写法哪里不好</span></a></h2><h3 id="问题一-一个函数干了四份活-违背单一职责" tabindex="-1"><a class="header-anchor" href="#问题一-一个函数干了四份活-违背单一职责"><span>问题一：一个函数干了四份活（违背单一职责）</span></a></h3><p><code>calcShipping</code> 里塞了四套互不相干的计费逻辑，后果是：</p><ul><li><strong>牵一发动全身</strong>：任何一个分支写崩了（比如手滑把 <code>amount</code> 写成 <code>amout</code>），整个运费函数都可能出错，四种配送方式一起受影响。</li><li><strong>定位困难</strong>：线上运费算错时，要在一个越来越长的函数里逐个分支排查。</li><li><strong>没法单独复用</strong>：别的页面（比如商品详情页的「预估运费」）只想用同城闪送的算法，只能把那段代码复制出去。复制品和原逻辑从此分叉，原规则一改，复制的地方就得跟着找出来再改一遍。</li></ul><p>看到一个函数里装着多块独立逻辑，第一反应就应该是：拆。</p><h3 id="问题二-加需求只能改老函数-违背开放封闭" tabindex="-1"><a class="header-anchor" href="#问题二-加需求只能改老函数-违背开放封闭"><span>问题二：加需求只能改老函数（违背开放封闭）</span></a></h3><p>假设运营又提了一个需求：生鲜商品支持「冷链配送」，固定 25 元，订单满 300 元免运费。在现有写法下，只能打开 <code>calcShipping</code>，在末尾再追加一段：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">function</span> <span class="token function">calcShipping</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> order</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> amount<span class="token punctuation">,</span> weight <span class="token punctuation">}</span> <span class="token operator">=</span> order<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;standard&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">99</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">8</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;express&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">199</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">15</span> <span class="token operator">/</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">15</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;sameDay&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> extraKg <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">ceil</span><span class="token punctuation">(</span>weight<span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">12</span> <span class="token operator">+</span> extraKg <span class="token operator">*</span> <span class="token number">4</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;pickup&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 新增：冷链配送</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;coldChain&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">300</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">25</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>改动看起来只有几行，但被修改的是<strong>所有配送方式共用的那个函数体</strong>。从测试的角度看，谁也不能保证这次没碰坏前面的分支，于是只能把四种老的配送方式连同新功能一起完整回归一遍。需求每加一次，这份不必要的回归成本就付一次。</p><p><img src="`+t+`" alt="新增冷链配送时，if-else 写法要改动共用函数体、全量回归；策略表写法只新增一行映射，只测新策略"></p><h2 id="重构第一步-每种算法各自独立" tabindex="-1"><a class="header-anchor" href="#重构第一步-每种算法各自独立"><span>重构第一步：每种算法各自独立</span></a></h2><p>先处理问题一。把四段计费逻辑分别搬进自己的函数，原来的大函数只负责判断该调谁：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// 普通快递</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">standardFee</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> amount <span class="token operator">&gt;=</span> <span class="token number">99</span> <span class="token operator">?</span> <span class="token number">0</span> <span class="token operator">:</span> <span class="token number">8</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 次日达</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">expressFee</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> amount <span class="token operator">&gt;=</span> <span class="token number">199</span> <span class="token operator">?</span> <span class="token number">7.5</span> <span class="token operator">:</span> <span class="token number">15</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 同城闪送</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">sameDayFee</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> weight <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token number">12</span> <span class="token operator">+</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">ceil</span><span class="token punctuation">(</span>weight<span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">4</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 门店自提</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">pickupFee</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">calcShipping</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> order</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;standard&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">standardFee</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;express&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">expressFee</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;sameDay&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">sameDayFee</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;pickup&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">pickupFee</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>现在每个函数的职责一目了然：</p><table><thead><tr><th>函数</th><th>职责</th></tr></thead><tbody><tr><td><code>standardFee</code></td><td>计算普通快递运费</td></tr><tr><td><code>expressFee</code></td><td>计算次日达运费</td></tr><tr><td><code>sameDayFee</code></td><td>计算同城闪送运费</td></tr><tr><td><code>pickupFee</code></td><td>计算门店自提运费</td></tr><tr><td><code>calcShipping</code></td><td>根据配送方式，把订单交给对应的计算函数</td></tr></tbody></table><p>收益立刻就有了：</p><ul><li>哪种配送方式算错了，就去看哪个函数，不用在一大坨代码里翻找；</li><li>商品详情页要预估闪送运费，直接 <code>import { sameDayFee }</code> 调用即可，规则以后改了也只改这一处；</li><li>每个计费函数都是纯函数，可以单独写单元测试。</li></ul><p>回头看整个流程，其实只有两个动作：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre class="language-text"><code><span class="line">选出该用哪种算法（分发）  ──&gt;  用这种算法算出结果（执行）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>第一步重构把「执行」拆了出去，各种算法之间已经互不干扰。但「分发」还是那串 if，新增冷链配送时依然要改 <code>calcShipping</code>：先写一个 <code>coldChainFee</code>，再往 <code>calcShipping</code> 里补一行 <code>if (method === &#39;coldChain&#39;) return coldChainFee(order)</code>。函数体照样被动了，开放封闭的问题没有解决。</p><h2 id="重构第二步-用映射表取代条件分支" tabindex="-1"><a class="header-anchor" href="#重构第二步-用映射表取代条件分支"><span>重构第二步：用映射表取代条件分支</span></a></h2><p>那一串 if 本质上在表达什么？其实只是「配送方式标识 → 计费函数」这一层对应关系。而 JavaScript 里表达「键 → 值」对应关系最自然的工具，就是对象（或 <code>Map</code>）。</p><p>把所有策略收进一张表：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> shippingStrategies <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">standard</span><span class="token operator">:</span> standardFee<span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">express</span><span class="token operator">:</span> expressFee<span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">sameDay</span><span class="token operator">:</span> sameDayFee<span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">pickup</span><span class="token operator">:</span> pickupFee<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>分发函数退化成一次查表：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">function</span> <span class="token function">quoteShipping</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> order</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> strategy <span class="token operator">=</span> shippingStrategies<span class="token punctuation">[</span>method<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>strategy<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">未知的配送方式：</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>method<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">strategy</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>（原始的 if-else 版本遇到没有定义的配送方式会默默返回 <code>undefined</code>，这种错误往往要到页面上显示出 <code>NaN</code> 才会被发现，所以这里顺手加了一个显式的报错。）</p><p>这时候再接冷链配送的需求，只需要<strong>新增</strong>一条映射，<code>quoteShipping</code> 和已有的四个策略一个字符都不用碰：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">function</span> <span class="token function">coldChainFee</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> amount <span class="token operator">&gt;=</span> <span class="token number">300</span> <span class="token operator">?</span> <span class="token number">0</span> <span class="token operator">:</span> <span class="token number">25</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">shippingStrategies<span class="token punctuation">.</span>coldChain <span class="token operator">=</span> coldChainFee<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">quoteShipping</span><span class="token punctuation">(</span><span class="token string">&#39;coldChain&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">amount</span><span class="token operator">:</span> <span class="token number">120</span><span class="token punctuation">,</span> <span class="token literal-property property">weight</span><span class="token operator">:</span> <span class="token number">2.3</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 25</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>提测的时候也就有底气了：这次只是加了一种配送方式，老的计费逻辑和分发逻辑都没改，只测冷链这一个新功能点就够。</p><p><img src="`+e+`" alt="策略模式的结构：调用方把配送方式交给分发函数，分发函数查策略表找到对应的计费函数执行，新增冷链只需加一行映射"></p><h2 id="回到定义" tabindex="-1"><a class="header-anchor" href="#回到定义"><span>回到定义</span></a></h2><p>整个重构走完，再看策略模式的定义：</p><blockquote><p>定义一系列算法，把它们逐个封装起来，并让它们可以相互替换。</p></blockquote><p>刚读这句话时容易觉得抽象：算法指什么？怎么封装？替换又是怎么做到的？对照上面的运费例子就具体了：</p><table><thead><tr><th>定义里的词</th><th>在运费例子里的样子</th></tr></thead><tbody><tr><td>一系列算法</td><td>五种配送方式各自的计费规则。「算法」不一定是排序、搜索那种，任何一段功能逻辑都算</td></tr><tr><td>封装</td><td>把每种规则抽成一个独立的计费函数（<code>standardFee</code>、<code>expressFee</code>……）</td></tr><tr><td>相互替换</td><td>所有计费函数签名一致（都接收 <code>order</code>、返回数字），调用方换一个 key 就换了一种算法；选择过程交给映射表，而不是硬写 if-else</td></tr></tbody></table><p>也就是说，「可替换」是建立在「封装」之上的：先把算法拆干净、接口统一，再找一个比条件判断更好的映射方式来做选择。</p><h2 id="策略模式的经典形态-面向对象写法" tabindex="-1"><a class="header-anchor" href="#策略模式的经典形态-面向对象写法"><span>策略模式的经典形态（面向对象写法）</span></a></h2><p>在 GoF 的原始描述里，策略模式通常有三个角色：</p><ul><li><strong>Strategy（策略接口）</strong>：规定所有策略必须提供的方法，比如 <code>calc(order)</code>；</li><li><strong>ConcreteStrategy（具体策略）</strong>：实现这个接口的各个类；</li><li><strong>Context（上下文）</strong>：持有一个策略对象，把具体计算委托给它，并且可以在运行时更换策略。</li></ul><p>用 class 写出来是这样：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">StandardShipping</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">calc</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> amount <span class="token operator">&gt;=</span> <span class="token number">99</span> <span class="token operator">?</span> <span class="token number">0</span> <span class="token operator">:</span> <span class="token number">8</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">SameDayShipping</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">calc</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> weight <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">12</span> <span class="token operator">+</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">ceil</span><span class="token punctuation">(</span>weight<span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">4</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">Checkout</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token parameter">shipping</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>shipping <span class="token operator">=</span> shipping<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token function">setShipping</span><span class="token punctuation">(</span><span class="token parameter">shipping</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>shipping <span class="token operator">=</span> shipping<span class="token punctuation">;</span> <span class="token comment">// 运行时切换策略</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token function">total</span><span class="token punctuation">(</span><span class="token parameter">order</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> order<span class="token punctuation">.</span>amount <span class="token operator">+</span> <span class="token keyword">this</span><span class="token punctuation">.</span>shipping<span class="token punctuation">.</span><span class="token function">calc</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> cart <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">amount</span><span class="token operator">:</span> <span class="token number">60</span><span class="token punctuation">,</span> <span class="token literal-property property">weight</span><span class="token operator">:</span> <span class="token number">3.2</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> checkout <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Checkout</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">StandardShipping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">checkout<span class="token punctuation">.</span><span class="token function">total</span><span class="token punctuation">(</span>cart<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 68</span></span>
<span class="line"></span>
<span class="line">checkout<span class="token punctuation">.</span><span class="token function">setShipping</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">SameDayShipping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">checkout<span class="token punctuation">.</span><span class="token function">total</span><span class="token punctuation">(</span>cart<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 84</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>JavaScript 里函数是一等公民，一个策略往往就是一个函数，所以前面「对象 + 函数」的写法是同一个思想的轻量版本：对象映射充当了 Context 选择策略的那部分职责，函数本身就是 ConcreteStrategy。两种写法任选，策略需要携带状态或多个方法时用 class 更合适，只有一个计算逻辑时用函数更简洁。</p><h2 id="工程实践中的几个细节" tabindex="-1"><a class="header-anchor" href="#工程实践中的几个细节"><span>工程实践中的几个细节</span></a></h2><h3 id="_1-把策略表封装进模块" tabindex="-1"><a class="header-anchor" href="#_1-把策略表封装进模块"><span>1. 把策略表封装进模块</span></a></h3><p>策略表属于实现细节，不应该让调用方随意读写。通常的做法是放在一个模块里，只导出需要的方法：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// shipping.js</span></span>
<span class="line"><span class="token keyword">const</span> shippingStrategies <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">standard</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">99</span> <span class="token operator">?</span> <span class="token number">0</span> <span class="token operator">:</span> <span class="token number">8</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">express</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">199</span> <span class="token operator">?</span> <span class="token number">7.5</span> <span class="token operator">:</span> <span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">sameDay</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> weight <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token number">12</span> <span class="token operator">+</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">ceil</span><span class="token punctuation">(</span>weight<span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">4</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">pickup</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">quoteShipping</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> order</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>Object<span class="token punctuation">.</span><span class="token function">hasOwn</span><span class="token punctuation">(</span>shippingStrategies<span class="token punctuation">,</span> method<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">未知的配送方式：</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>method<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> shippingStrategies<span class="token punctuation">[</span>method<span class="token punctuation">]</span><span class="token punctuation">(</span>order<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 需要开放扩展时，提供一个注册入口而不是把整张表导出去</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">registerShipping</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> strategy</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  shippingStrategies<span class="token punctuation">[</span>method<span class="token punctuation">]</span> <span class="token operator">=</span> strategy<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// checkout.js</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> quoteShipping<span class="token punctuation">,</span> registerShipping <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./shipping.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">registerShipping</span><span class="token punctuation">(</span><span class="token string">&#39;coldChain&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> amount <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span>amount <span class="token operator">&gt;=</span> <span class="token number">300</span> <span class="token operator">?</span> <span class="token number">0</span> <span class="token operator">:</span> <span class="token number">25</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">quoteShipping</span><span class="token punctuation">(</span><span class="token string">&#39;coldChain&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">amount</span><span class="token operator">:</span> <span class="token number">320</span><span class="token punctuation">,</span> <span class="token literal-property property">weight</span><span class="token operator">:</span> <span class="token number">5</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 0</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-小心未知-key-和原型链" tabindex="-1"><a class="header-anchor" href="#_2-小心未知-key-和原型链"><span>2. 小心未知 key 和原型链</span></a></h3><p>直接 <code>shippingStrategies[method]</code> 查表有个隐患：普通对象会继承 <code>Object.prototype</code> 上的属性。如果 <code>method</code> 来自接口或 URL 参数，传进来一个 <code>&#39;toString&#39;</code>，查到的是一个真实存在的函数，不会进入「未知配送方式」的分支，而是返回一个莫名其妙的字符串。几种规避方式：</p><table><thead><tr><th>做法</th><th>写法</th></tr></thead><tbody><tr><td>判断自有属性</td><td><code>Object.hasOwn(table, key)</code>（旧环境用 <code>Object.prototype.hasOwnProperty.call(table, key)</code>）</td></tr><tr><td>创建无原型对象</td><td><code>const table = Object.assign(Object.create(null), { ... })</code></td></tr><tr><td>改用 Map</td><td><code>const table = new Map([[&#39;standard&#39;, standardFee], ...])</code>，用 <code>table.get(key)</code> 取值</td></tr></tbody></table><h3 id="_3-策略模式不只用来算价格" tabindex="-1"><a class="header-anchor" href="#_3-策略模式不只用来算价格"><span>3. 策略模式不只用来算价格</span></a></h3><p>只要是「同一件事，有多种做法，按条件选一种」，都可以套这个结构。表单校验就是一个经典例子：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> validators <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">required</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">value</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span>value<span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string">&#39;&#39;</span> <span class="token operator">?</span> <span class="token string">&#39;不能为空&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">minLength</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">value<span class="token punctuation">,</span> n</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span>value<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> n <span class="token operator">?</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">至少 </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>n<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> 个字符</span><span class="token template-punctuation string">\`</span></span> <span class="token operator">:</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">phone</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">value</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^1\\d{10}$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token string">&#39;&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;手机号格式不对&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// rules 形如 [[&#39;required&#39;], [&#39;minLength&#39;, 6]]，按顺序执行，遇到第一个错误就返回</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">validate</span><span class="token punctuation">(</span><span class="token parameter">value<span class="token punctuation">,</span> rules</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token punctuation">[</span>name<span class="token punctuation">,</span> <span class="token operator">...</span>args<span class="token punctuation">]</span> <span class="token keyword">of</span> rules<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> message <span class="token operator">=</span> validators<span class="token punctuation">[</span>name<span class="token punctuation">]</span><span class="token punctuation">(</span>value<span class="token punctuation">,</span> <span class="token operator">...</span>args<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>message<span class="token punctuation">)</span> <span class="token keyword">return</span> message<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token function">validate</span><span class="token punctuation">(</span><span class="token string">&#39;&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;不能为空&#39;</span></span>
<span class="line"><span class="token function">validate</span><span class="token punctuation">(</span><span class="token string">&#39;abc&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string">&#39;minLength&#39;</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;至少 6 个字符&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>新增一种校验规则（比如邮箱）只需往 <code>validators</code> 里加一项，<code>validate</code> 不用改。其他常见场景还有：埋点在不同环境下选择 <code>sendBeacon</code> / 图片打点 / <code>fetch</code> 上报，动画库里 <code>linear</code>、<code>ease-in</code> 等缓动函数，按用户角色渲染不同的操作按钮等。</p><h2 id="优点与代价" tabindex="-1"><a class="header-anchor" href="#优点与代价"><span>优点与代价</span></a></h2><table><thead><tr><th>优点</th><th>代价 / 注意</th></tr></thead><tbody><tr><td>消除大量 if-else / switch，分发逻辑一眼看懂</td><td>策略数量多时，文件和函数会变多，需要合理组织目录</td></tr><tr><td>每个策略可以单独复用、单独测试</td><td>调用方要知道有哪些 key 可用（可以用常量或 TypeScript 联合类型约束）</td></tr><tr><td>新增策略不改老代码，回归范围小</td><td>只有两三个且基本不会再变的分支时，直接写 if 反而更直白，不必为了模式而模式</td></tr><tr><td>策略可在运行时动态切换或注册</td><td>策略之间如果需要共享大量数据，接口设计要更小心</td></tr></tbody></table><h2 id="面试速答模板" tabindex="-1"><a class="header-anchor" href="#面试速答模板"><span>面试速答模板</span></a></h2><blockquote><p>策略模式就是把一组做同一类事情的算法分别封装起来，并且让它们接口一致、可以互相替换，调用时根据条件选一个来执行。在 JS 里最常见的写法是用一个对象做映射：key 是类型，value 是对应的处理函数，分发函数只做一次查表。比如运费计算，原本一个函数里用 if-else 处理普通快递、次日达、闪送、自提四种规则，既违背单一职责，一个分支出错会影响全部、也没法单独复用，又违背开放封闭，每加一种配送方式都得改这个函数、测试要整体回归。重构分两步：先把每种规则拆成独立函数，解决执行层面的耦合；再用对象映射替代 if-else，解决分发层面的问题，之后新增配送方式只需要往表里加一项，测试也只测新增的部分。实际使用时我会把策略表封装在模块里只导出入口方法，并且对未知 key 做兜底，用 <code>Object.hasOwn</code> 或 Map 避免命中原型上的属性。表单校验、价格折扣、埋点上报方式选择都是它的典型应用。</p></blockquote>`,77),l=[c];function i(u,r){return a(),s("div",null,l)}const d=n(o,[["render",i],["__file","06-6-行为型-策略模式.html.vue"]]),m=JSON.parse('{"path":"/%E5%B8%B8%E7%94%A8%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F/06-6-%E8%A1%8C%E4%B8%BA%E5%9E%8B-%E7%AD%96%E7%95%A5%E6%A8%A1%E5%BC%8F.html","title":"行为型 策略模式","lang":"zh-CN","frontmatter":{"title":"行为型 策略模式","description":"策略模式（Strategy） 核心要点 定义：把一组做同类事情的算法分别封装成独立的单元，让它们对外长得一样（入参、返回值一致），从而可以随时互相替换。 一句话理解：同一个入口，传进来的「类型 / 参数」不同，就命中不同的处理策略。 三个关键词怎么落地： 「算法」：任何一段业务计算逻辑，比如运费怎么算、积分怎么给、字段怎么校验； 「封装」：把每种逻辑单...","head":[["meta",{"property":"og:url","content":"https://interview.leeguoo.com/%E5%B8%B8%E7%94%A8%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F/06-6-%E8%A1%8C%E4%B8%BA%E5%9E%8B-%E7%AD%96%E7%95%A5%E6%A8%A1%E5%BC%8F.html"}],["meta",{"property":"og:site_name","content":"前端面试题集锦"}],["meta",{"property":"og:title","content":"行为型 策略模式"}],["meta",{"property":"og:description","content":"策略模式（Strategy） 核心要点 定义：把一组做同类事情的算法分别封装成独立的单元，让它们对外长得一样（入参、返回值一致），从而可以随时互相替换。 一句话理解：同一个入口，传进来的「类型 / 参数」不同，就命中不同的处理策略。 三个关键词怎么落地： 「算法」：任何一段业务计算逻辑，比如运费怎么算、积分怎么给、字段怎么校验； 「封装」：把每种逻辑单..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://interview.leeguoo.com/images/rewrite/pattern-strategy/change-scope.webp"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-02T11:46:12.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-02T11:46:12.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"行为型 策略模式\\",\\"image\\":[\\"https://interview.leeguoo.com/images/rewrite/pattern-strategy/change-scope.webp\\",\\"https://interview.leeguoo.com/images/rewrite/pattern-strategy/structure.webp\\"],\\"dateModified\\":\\"2026-10-02T11:46:12.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"核心要点","slug":"核心要点","link":"#核心要点","children":[]},{"level":2,"title":"先看一个最小例子","slug":"先看一个最小例子","link":"#先看一个最小例子","children":[]},{"level":2,"title":"实战场景：结算页的运费计算","slug":"实战场景-结算页的运费计算","link":"#实战场景-结算页的运费计算","children":[{"level":3,"title":"直觉写法：一个函数包办一切","slug":"直觉写法-一个函数包办一切","link":"#直觉写法-一个函数包办一切","children":[]}]},{"level":2,"title":"这种写法哪里不好","slug":"这种写法哪里不好","link":"#这种写法哪里不好","children":[{"level":3,"title":"问题一：一个函数干了四份活（违背单一职责）","slug":"问题一-一个函数干了四份活-违背单一职责","link":"#问题一-一个函数干了四份活-违背单一职责","children":[]},{"level":3,"title":"问题二：加需求只能改老函数（违背开放封闭）","slug":"问题二-加需求只能改老函数-违背开放封闭","link":"#问题二-加需求只能改老函数-违背开放封闭","children":[]}]},{"level":2,"title":"重构第一步：每种算法各自独立","slug":"重构第一步-每种算法各自独立","link":"#重构第一步-每种算法各自独立","children":[]},{"level":2,"title":"重构第二步：用映射表取代条件分支","slug":"重构第二步-用映射表取代条件分支","link":"#重构第二步-用映射表取代条件分支","children":[]},{"level":2,"title":"回到定义","slug":"回到定义","link":"#回到定义","children":[]},{"level":2,"title":"策略模式的经典形态（面向对象写法）","slug":"策略模式的经典形态-面向对象写法","link":"#策略模式的经典形态-面向对象写法","children":[]},{"level":2,"title":"工程实践中的几个细节","slug":"工程实践中的几个细节","link":"#工程实践中的几个细节","children":[{"level":3,"title":"1. 把策略表封装进模块","slug":"_1-把策略表封装进模块","link":"#_1-把策略表封装进模块","children":[]},{"level":3,"title":"2. 小心未知 key 和原型链","slug":"_2-小心未知-key-和原型链","link":"#_2-小心未知-key-和原型链","children":[]},{"level":3,"title":"3. 策略模式不只用来算价格","slug":"_3-策略模式不只用来算价格","link":"#_3-策略模式不只用来算价格","children":[]}]},{"level":2,"title":"优点与代价","slug":"优点与代价","link":"#优点与代价","children":[]},{"level":2,"title":"面试速答模板","slug":"面试速答模板","link":"#面试速答模板","children":[]}],"git":{"updatedTime":1790941572000,"contributors":[{"name":"leeguooooo","email":"guoli@zhihu.com","commits":3}]},"autoDesc":true,"filePathRelative":"常用设计模式/06-6-行为型-策略模式.md","excerpt":"\\n<h2>核心要点</h2>\\n<ul>\\n<li><strong>定义</strong>：把一组做同类事情的算法分别封装成独立的单元，让它们对外长得一样（入参、返回值一致），从而可以随时互相替换。</li>\\n<li><strong>一句话理解</strong>：同一个入口，传进来的「类型 / 参数」不同，就命中不同的处理策略。</li>\\n<li><strong>三个关键词怎么落地</strong>：\\n<ul>\\n<li>「算法」：任何一段业务计算逻辑，比如运费怎么算、积分怎么给、字段怎么校验；</li>\\n<li>「封装」：把每种逻辑单独抽成一个函数（或类），各管各的；</li>\\n<li>「可替换」：用一张「key → 策略」的映射表来选择策略，而不是在一个函数里堆 if-else。</li>\\n</ul>\\n</li>\\n<li><strong>好处</strong>：干掉成片的 if-else / switch；每个策略可以单独复用、单独测试；新增一种情况只加一条映射，不改老代码。</li>\\n<li><strong>背后的两条设计原则</strong>：\\n<ul>\\n<li>单一职责：一个函数只处理一种算法，出 Bug 能精确定位，修一个不会连累其他；</li>\\n<li>开放封闭：对扩展开放（加新策略）、对修改封闭（分发逻辑和老策略不动），测试只需要覆盖新增的那条。</li>\\n</ul>\\n</li>\\n<li><strong>重构路线</strong>：if-else 大函数 → 先把每段逻辑拆成独立函数（解决「执行」）→ 再用对象映射取代条件判断（解决「分发」）。</li>\\n<li><strong>工程上的封装</strong>：策略表和分发函数放进一个模块，只 <code>export</code> 对外的方法，调用方 <code>import</code> 后按 key 调用。</li>\\n<li><strong>常见应用</strong>：价格 / 运费 / 折扣计算、表单校验规则、不同环境的上报方式、动画缓动函数、权限或路由的分支处理。</li>\\n<li><strong>补充注意点</strong>：查表前要处理未知 key（否则会报 <code>xxx is not a function</code>，普通对象还可能命中原型上的 <code>toString</code> 之类的方法），可以用 <code>Object.hasOwn</code>、<code>Object.create(null)</code> 或 <code>Map</code>。</li>\\n</ul>"}');export{d as comp,m as data};
